import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { pathToFileURL } from 'node:url';

export async function gate({ referenceDir, submissionDir }) {
  const submissionFile = path.join(submissionDir, 'answer.mjs');
  const pinnedFile = path.join(referenceDir, 'pinned-test-cases.txt');
  const runnerFile = path.join(referenceDir, '_gate_runner.mjs');

  if (!fs.existsSync(submissionFile)) {
    return { accept: false, reason: 'submission missing answer.mjs' };
  }
  if (!fs.existsSync(pinnedFile)) {
    return { accept: false, reason: 'pinned-test-cases.txt not found' };
  }

  const pinned = fs.readFileSync(pinnedFile, 'utf8');
  const submissionUrl = pathToFileURL(path.resolve(submissionFile)).href;

  const runner = [
    "import { test } from 'node:test';",
    "import assert from 'node:assert/strict';",
    "const __mod = await import(" + JSON.stringify(submissionUrl) + ");",
    "const dedupeSorted = __mod.dedupeSorted;",
    "if (typeof dedupeSorted !== 'function') {",
    "  console.error('dedupeSorted export missing or not a function');",
    "  process.exit(2);",
    "}",
    pinned
  ].join('\n');

  fs.writeFileSync(runnerFile, runner, 'utf8');

  const outcome = await new Promise((resolve) => {
    const child = spawn(process.execPath, ['--test', runnerFile], {
      stdio: ['ignore', 'pipe', 'pipe']
    });
    let stdout = '';
    let stderr = '';
    const timer = setTimeout(() => {
      try { child.kill('SIGKILL'); } catch {}
      resolve({ code: 1, stdout, stderr: stderr + '\ntimeout' });
    }, 25000);
    child.stdout.on('data', (d) => { stdout += d.toString(); });
    child.stderr.on('data', (d) => { stderr += d.toString(); });
    child.on('close', (code) => {
      clearTimeout(timer);
      resolve({ code: code == null ? 1 : code, stdout, stderr });
    });
    child.on('error', (err) => {
      clearTimeout(timer);
      resolve({ code: 1, stdout, stderr: String(err) });
    });
  });

  if (outcome.code === 0) {
    return { accept: true, reason: 'all pinned tests passed' };
  }
  const detail = (outcome.stderr + '\n' + outcome.stdout).trim().slice(0, 800);
  return { accept: false, reason: 'pinned tests failed (exit ' + outcome.code + '): ' + detail };
}

